from definition import *
def wait(t):return dict(action='WAIT',until=t)
def finish(text):return dict(action='FINISH',text=text)
def hist(a,b,c):return [('routine explanation',a),('prior correction',b),('uncertain request',c)]
def add_case(*,initial,reply,follow_reply,updates,alternative_updates,wrong_initial,near_target,near_text,handoff,alternative_handoff=None,**c):
 'Compose explicit plans; changes remain case-authored, never scored here.'
 initial_ops=[W('main',initial[0],status='published',assets=c.pop('correct_initial_assets',[])),W('old',initial[1])]+c.pop('initial_ops',[])
 plan=initial_ops+[P('q',reply,'a1')]
 plan += [wait(len(plan)+2),P('followup',follow_reply,'a2')]
 prefix=deepcopy(plan); near_index=None
 for e,ops in zip(c['events'],updates):
  plan.append(wait(e['at']))
  for op in ops:
   if op.get('target')==near_target:near_index=len(plan)
   plan.append(op)
 plan += [wait(50),finish(handoff)]
 alt=prefix
 for e,ops in zip(c['events'],alternative_updates):alt += [wait(e['at'])]+deepcopy(ops)
 alt += [wait(50),finish(alternative_handoff or handoff)]
 assert near_index is not None
 wrong=deepcopy(plan[near_index]);wrong['text']=near_text
 c.update(plan=plan,alternative=alt,failure_initial=dict(index=0,action=W('main',wrong_initial,status='published'),reason='The initial main text contradicts the supplied evidence; G1 fails even if later repaired.'),failure_near=dict(index=near_index,action=wrong,reason='Only this dependent object retains the wrong current claim; other repairs and deliveries are correct. G3 fails.'))
 C(**c)

