add_case(id='t2-02',seed=5,title='Within rent is not within the monthly cap',domain='home_living',difficulty='medium',template='inclusive-budget-versus-mandatory-itemized-fees',task='Help Milo Home maintain a fictional rental shortlist and answer a reader whose monthly cap includes every mandatory fee. Recommend only from the provided listings; do not arrange a tenancy or disclose private contact details.',main='Listing L rent 900 fits any 1000 monthly budget.',old='Service fees do not count toward an all-inclusive cap.',question='My total monthly cap is 1000 including mandatory fees. Does L really fit?',facts="Listing L: rent 900, mandatory service 70, no other mandatory fee currently listed. Listing M:950 all-inclusive. Both otherwise meet the reader's stated needs. Only listed fees may be counted; unknown charges cannot be invented. A public shortlist may exclude over-budget listings or label them explicitly excluded.",protected='Listing M remains 950 all-inclusive with unchanged terms.',style='Use simple totals and avoid pushing the reader past their stated limit.',history=[('moving checklist','Start with the items you will need on the first night.'),('broken map link','I have fixed the map link. Thanks for flagging it.'),("reader's preference",'If that layout does not suit you, we can leave it out.')],style_exception='A fixed budget is a constraint, not an invitation to upsell.',events=[E(18,'L manager adds mandatory monthly heat 60 to the listing. Rent 900 and service 70 remain. M terms are unchanged.',affects=['shortlist eligibility','budget answer'],due=30)],feedback=dict(text='Please do not suggest stretching my budget if another mandatory charge appears.',affects=['shortlist'],delay=2),initial_objects=['main','old'],initial_condition='State the initial 970 total and count the service fee; M remains 950. Do not promise unknown charges are impossible.',conversation_condition='Answer against the inclusive cap and respect the reader refusal to stretch it.',maintenance_objects=['main','old','dependent budget answer'],maintenance_condition='After notice calculate 1030, above 1000, and remove L from eligible recommendations or mark it excluded. Preserve M and correct prior current eligibility statements.',legal_branches=['Remove L from the shortlist and retain M.','Keep L in a clearly excluded comparison section with its total, retaining M as eligible.'],initial=['L currently totals 970: rent 900 plus service 70. This fits the 1000 cap on the supplied fee list; M is 950 all-inclusive.','Correction: mandatory service belongs in an inclusive monthly total.'],reply='On the current list, L is 970 including service 70, so it fits. M is 950 all-inclusive. I will revise this if another mandatory fee appears.',follow_reply='Understood. I will apply your 1000 cap to the full mandatory total, not suggest stretching it.',updates=[u],alternative_updates=[a],wrong_initial='L fits because rent 900 is below 1000; mandatory service does not count.',near_target='a1',near_text='L still fits your 1000 inclusive cap after the heat charge.',handoff='L is excluded at 1030; M remains 950. Milo owns any later viewing enquiry; no tenancy or viewing was arranged.',decision=dict(core_misunderstanding='Headline rent is not the constrained total.',update_trigger='New mandatory charge changes eligibility',decision_change='Remove only the affected eligible listing; preserve alternative.',affected_objects=['shortlist','old fee rule','reader answer'],notification_support='facts_only'))

