add_case(id='t3-03',seed=8,title='One wash test, two batch labels',domain='beauty_fashion',difficulty='medium',template='batch-scoped-measurement-versus-shared-product-title',task="Maintain Faye Fit's trouser measurement post. Distinguish batch labels and measurement states; use the supplied wash test without inventing garment-care advice or a universal shrinkage promise.",main='Every pair under this product title has the same after-wash length.',old='Batch letters do not matter when the shop title is identical.',question='Mine is batch S. Can I use your batch R result when deciding the length?',facts='R and S share a product title and each measured 100 cm before washing. Their fabric lots differ. The only planned wash test concerns R. Measurements describe these samples, not individual fit or universal wash behavior. The separate waistband chart is unchanged. No physical washing or alteration is authorized.',protected='The waistband chart reports unwashed measurements and remains accurate.',style='Be approachable and specific about the garment being discussed.',history=[('outfit photo','The green scarf works nicely with that coat.'),('size-label typo','Thanks; I transposed the label and have corrected it.'),('reader uncertainty','If the cut feels wrong for you, there is no need to force it.')],style_exception='Do not dismiss a careful batch-label question as overthinking.',events=[E(24,'R test result:100 cm before,98 cm after the specified wash. No S test was performed. Both batch labels remain unchanged.',affects=['measurement post','S answer'],due=36)],feedback=dict(text='The title and original length match. Does that make the two batches equivalent for shrinkage?',affects=['scope of evidence'],delay=2),initial_objects=['main','old'],initial_condition='Remove the shared after-wash guarantee and preserve the distinction between R/S and before/after states.',conversation_condition='Explain that a shared title and initial measurement do not establish identical response to washing.',maintenance_objects=['main','old','batch-specific reader answer'],maintenance_condition="Report R 100-to 98 accurately; preserve S unknown after-wash state. Do not globally replace every 100 with 98 or promise S's shrinkage.",legal_branches=['Publish the R-scoped result with S uncertainty.','Hold shared sizing advice while retaining separate verified measurements.'],initial=['R and S both measure 100 cm before washing, but only R is being tested. There is no shared after-wash result.','Correction: the batch label matters because the fabric lots differ.'],reply='Not as a result for S. R can inform only its own sample unless S is tested under comparable conditions.',follow_reply='No. Matching titles and starting lengths do not establish identical shrinkage in different fabric lots.',updates=[u],alternative_updates=[a],wrong_initial='The common title proves both batches share the same after-wash length.',near_target='a1',near_text='Your S pair is confirmed 98 cm after washing because R measured 98 cm.',handoff='Faye owns any S test or fit advice. R 98 cm is scoped to the tested sample; S after-wash length remains unknown.',decision=dict(core_misunderstanding='Shared naming is not shared measurement scope.',update_trigger='Scoped test result',decision_change='Update only the tested batch and preserve unknown state elsewhere.',affected_objects=['measurement guide','old generalization','S answer'],notification_support='facts_only'))

