add_case(id='t4-02',seed=15,title='A design transfer with separate uses',domain='creative_arts_crafts',difficulty='hard',template='transfer-title-versus-separated-derivative-resale-and-commercial-rights',task="Maintain Kira Sketch's fictional character-adoption announcement and file preview. Apply the exact uses in the supplied transfer card; a transfer label does not grant every use of every file.",main='Adopting the character transfers all rights, including resale and business branding.',old='Permission to edit means permission to sell the original file.',question='If I adopt the design, can I redraw it, resell the original file, and make it my shop mascot?',facts='Initial transfer card: recipient may keep the character in a personal collection. Editing, sharing and commercial uses are not yet granted. Original-file remains the designer supplied work. Creator may use a text-only announcement pending clarification. The preview currently attaches original-file without public-sharing permission. The unrelated creator-owned logo is separately licensed for the creator business.',protected='The creator-owned business logo remains available under its separate permission.',assets=['original-file','personal-redraw'],initial_assets=['original-file'],correct_initial_assets=[],style='Explain permissions in ordinary language without treating the question as theft.',history=[('drawing encouragement','Your first sketch has a lovely sense of movement.'),('credit correction','I missed the colorist name. It is now included.'),('busy week','I am behind on replies this week; thank you for waiting.')],style_exception='Questions about a transfer need scope clarification, not accusation.',events=[E(20,'Designer clarification: personal redraws may be shared with credit to original designer Ilex. This does not grant resale of original-file or commercial mascot use. A supplied personal-redraw preview is licensed for this personal announcement with credit.',affects=['preview asset','permission explanation'],due=34)],feedback=dict(text='If redraws are allowed, does changing the colors make business use personal?',affects=['purpose boundary'],delay=2),initial_objects=['main','old','attachments'],initial_condition='Remove broad all-rights and edit-to-resale claims. Remove unlicensed original-file preview; allow text-only hold.',conversation_condition='Separate possession, editing/sharing, original-file resale and commercial purpose; a color change does not make business use personal.',maintenance_objects=['main','old','permission answer','attachments'],maintenance_condition='Apply personal credited redraw permission only. If displaying the preview attach personal-redraw and give designer credit; text-only hold is equally valid. Keep original-file resale and business purpose ungranted.',legal_branches=['Display the licensed personal redraw with designer credit and explain excluded uses.','Keep text-only and hold commercial use while explaining the personal option.'],initial=['The transfer currently covers a personal collection only. Other uses need clarification; the preview is text-only.','Correction: possession of a design does not grant editing, resale or commercial use automatically.'],reply='The current card grants personal possession only. Redraw sharing, resale and shop-mascot use are separate questions requiring scope from the designer.',follow_reply='No. A business mascot is still a commercial purpose after a color change; the visual edit does not change that purpose.',updates=[u],alternative_updates=[a],wrong_initial='The adoption grants every use, including original-file resale and commercial mascot branding.',near_target='a1',near_text='The personal-redraw grant now permits selling the original design file and using it commercially.',handoff='Kira must seek separate commercial permission if desired. Personal sharing is scoped to credited redraws; original-file resale is not granted.',decision=dict(core_misunderstanding='Transfer and editing are not blanket rights across purpose and source asset.',update_trigger='Scope clarification expands one use while preserving exclusions',decision_change='Allow the narrow derivative branch or hold business use; preserve asset distinction.',affected_objects=['preview','permission claim','reader explanation'],notification_support='facts_only'))

