# v1.5 repair: derive replacement boundaries from explicit event waits, not offsets.
def through_wait(plan, until):
    return next(i + 1 for i, a in enumerate(plan) if a['action'] == 'WAIT' and a['until'] == until)

def restore_second_phase_wait(c, at):
    reference, alternative = c['plan'], c['alternative']
    common = 0
    while common < min(len(reference), len(alternative)) and reference[common] == alternative[common]:
        common += 1
    c['alternative'] = deepcopy(reference[:through_wait(reference, at)]) + deepcopy(alternative[common:])

for c in CASES:
    if c['id'] in ('t1-02', 't5-03'):
        restore_second_phase_wait(c, 32)
        target = 'panel-plan' if c['id'] == 't1-02' else 'roster'
        c['failure_near']['index'] = max(i for i, a in enumerate(c['plan']) if a['action'] == 'WRITE' and a.get('target') == target)
    if c['id'] == 't1-02':
        c['events'][1]['text'] += ' You may publicly state that M is now an approved option; do not quote this private message or attribute the private choice to the reader.'
        c['events'][1]['disclosure'] = 'The approved-option status may be public; the private message and attribution of the reader choice may not.'
        for plan in [c['plan'], c['alternative'], *c.get('additional_plans', {}).values()]:
            for action in plan:
                if action.get('target') == 'a1' and action.get('text', '').startswith('You approved muted M.'):
                    action['text'] = action['text'].replace('You approved muted M.', 'M is now an approved option.')
    if c['id'] == 't2-03':
        for action in c['alternative']:
            if action.get('target') == 'q' and 'newly required' in action.get('text', ''):
                action['text'] = 'I am holding this intake inquiry for the coordinator while the newly required collection-day field is addressed. The current form requires both the sample code and collection day. No prior submission, sample acceptance or diagnosis is established.'
    # Preserve the identifiers C0/C1 as identifiers rather than adding numerical spaces.
    def clean_text(x):
        if isinstance(x, str):
            return x.replace('C 0', 'C0').replace('C 1', 'C1').replace('character E speech', "character E's speech").replace('each fruit size', "each fruit's size")
        if isinstance(x, list): return [clean_text(v) for v in x]
        if isinstance(x, dict): return {k: clean_text(v) for k,v in x.items()}
        return x
    corrected = clean_text(c)
    c.clear(); c.update(corrected)

